<script setup lang="ts">
import { computed,ref } from 'vue';import{onLoad,onPullDownRefresh}from'@dcloudio/uni-app';import WareState from '@/shared/components/WareState.vue';import{cartonInventoryApi,type CartonStock,type CartonOptions}from'../../api/carton-inventory.api';
const stocks=ref<CartonStock[]>([]),options=ref<CartonOptions>({skus:[],parts:[]}),spec=ref(''),part=ref(''),loading=ref(true),error=ref('');
const partIndex=computed(()=>Math.max(0,options.value.parts.indexOf(part.value)));async function load(){loading.value=true;error.value='';try{const r=await cartonInventoryApi.overview(spec.value,part.value);stocks.value=r.stocks;options.value=r.options}catch(e){error.value=e instanceof Error?e.message:'纸箱库存加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}function go(path:string){uni.navigateTo({url:path})}function reset(){spec.value='';part.value='';load()}onLoad(load);onPullDownRefresh(load);
</script>
<template><view class="page"><view class="manage"><b>进销存管理</b><view class="actions"><view @click="go('/features/carton-inventory/pages/applications/index')"><image src="/static/icons/wms/fwms-task-outline.svg"/><b>申领审核</b><text>审核纸箱申领</text></view><view @click="go('/features/carton-inventory/pages/ledger/index?kind=inbound')"><image src="/static/icons/wms/fwms-inbound-outline.svg"/><b>入库管理</b><text>物资入库登记</text></view><view class="warn" @click="go('/features/carton-inventory/pages/ledger/index?kind=outbound')"><image src="/static/icons/wms/fwms-outbound-outline.svg"/><b>出库管理</b><text>物资出库登记</text></view></view></view><view class="title"><b>纸箱库存</b><text>实时查看各分区纸箱库存</text></view><view class="filters"><input v-model="spec" placeholder="搜索纸箱规格" @confirm="load"/><picker :range="['全部分区',...options.parts]" @change="part=Number($event.detail.value)?options.parts[Number($event.detail.value)-1]:''"><view>{{part||'全部分区'}}⌄</view></picker><button @click="reset">重置</button><button class="primary" @click="load">查询</button></view><view class="head"><text>物资名称</text><text>纸箱规格</text><text>分区</text><text>库存数量</text></view><WareState v-if="loading||error||!stocks.length" :type="loading ? 'loading' : error ? 'error' : 'empty'" :title="loading ? '正在加载' : error ? '加载失败' : '暂无纸箱库存'" :description="error" :action-label="error ? '重新加载' : undefined" @action="load"/><view v-else class="row" v-for="x in stocks" :key="x.id"><b>{{x.sku_name}}</b><text>{{x.specification}}</text><text>{{x.part}}</text><strong :class="{zero:+x.quantity===0}">● {{x.quantity}}{{x.unit}}</strong></view></view></template>
